describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    linearWebhookSecret: 'secret',
    linearApiBaseUrl: 'https://api.linear.app',
    linearApiToken: 'token',
    discordWebhookUrl: 'https://discord.com/api/webhooks/123/abc',
    timestampToleranceMs: 60000,
  };

  const baseTime = new Date('2024-01-23T12:53:18.084Z').getTime();

  function makePayload(overrides: Partial<LinearWebhookPayload> = {}): LinearWebhookPayload {
    return {
      action: 'update',
      type: 'Issue',
      data: {
        id: '2174add1-f7c8-44e3-bbf3-2d60b5ea8bc9',
        title: 'Fix login bug',
        identifier: 'LIN-123',
        state: { name: 'Closed' },
        url: 'https://linear.app/issue/LIN-123/fix-login-bug',
      },
      createdAt: '2024-01-23T12:53:18.084Z',
      webhookTimestamp: baseTime,
      ...overrides,
    };
  }

  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(baseTime);
  });

  it('posts formatted digest to Discord on happy path with pagination', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/issues/') && req.url.includes('/comments')) {
        if (req.url.includes('after=cursor1')) {
          return jsonResponse({
            comments: [
              {
                id: 'c3',
                author: { name: 'Bob', email: 'bob@example.com' },
                body: 'Third comment',
                createdAt: '2024-01-23T13:00:00Z',
              },
            ],
            pageInfo: { endCursor: 'cursor2', hasMore: false },
          });
        }
        return jsonResponse({
          comments: [
            {
              id: 'c1',
              author: { name: 'Alice', email: 'alice@example.com' },
              body: 'First comment',
              createdAt: '2024-01-23T12:55:00Z',
            },
            {
              id: 'c2',
              author: { name: 'Jane', email: 'jane@example.com' },
              body: 'Second comment',
              createdAt: '2024-01-23T12:56:00Z',
            },
          ],
          pageInfo: { endCursor: 'cursor1', hasMore: true },
        });
      }
      if (req.url === baseConfig.discordWebhookUrl) {
        return jsonResponse({ id: 'msg-123' }, 200);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const result = await handle(makePayload(), { ...baseConfig, fetch });
    expect(result.discordMessageId).toBe('msg-123');

    const discordCall = calls.find((c) => c.url === baseConfig.discordWebhookUrl);
    expect(discordCall).toBeDefined();
    expect(discordCall?.method).toBe('POST');
    expect(discordCall?.json).toEqual(
      expect.objectContaining({
        content: expect.stringContaining('Issue LIN-123: Fix login bug'),
        username: 'Linear Bot',
        avatar_url: 'https://linear.app/assets/icon.png',
      })
    );
    expect((discordCall?.json as any).content).toContain('Alice (alice@example.com): First comment');
    expect((discordCall?.json as any).content).toContain('Jane (jane@example.com): Second comment');
    expect((discordCall?.json as any).content).toContain('Bob (bob@example.com): Third comment');
  });

  it('validates required fields and throws descriptive errors', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));

    await expect(handle({ ...makePayload(), action: 'create' }, { ...baseConfig, fetch })).rejects.toThrow(
      'action must be "update"'
    );
    await expect(handle({ ...makePayload(), type: 'Project' }, { ...baseConfig, fetch })).rejects.toThrow(
      'type must be "Issue"'
    );
    await expect(handle({ ...makePayload(), data: { ...makePayload().data, state: { name: 'Open' } } }, { ...baseConfig, fetch })).rejects.toThrow(
      'issue state must be "Closed"'
    );
    await expect(handle({ ...makePayload(), data: { ...makePayload().data, id: '' } }, { ...baseConfig, fetch })).rejects.toThrow(
      'missing issue id'
    );
    await expect(handle({ ...makePayload(), data: { ...makePayload().data, title: '' } }, { ...baseConfig, fetch })).rejects.toThrow(
      'missing issue title'
    );
    await expect(handle({ ...makePayload(), data: { ...makePayload().data, identifier: '' } }, { ...baseConfig, fetch })).rejects.toThrow(
      'missing issue identifier'
    );
  });

  it('rejects stale webhook timestamp', async () => {
    vi.setSystemTime(baseTime + 120000); // 2 minutes later
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const stalePayload = makePayload({ webhookTimestamp: baseTime }); // 2 min old, tolerance 60s
    await expect(handle(stalePayload, { ...baseConfig, fetch })).rejects.toThrow('too old');
  });

  it('throws on non-2xx Discord response with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/issues/') && req.url.includes('/comments')) {
        return jsonResponse({ comments: [], pageInfo: { endCursor: '', hasMore: false } });
      }
      if (req.url === baseConfig.discordWebhookUrl) {
        return jsonResponse({ error: 'Unauthorized' }, 401);
      }
      return jsonResponse({}, 404);
    });

    await expect(handle(makePayload(), { ...baseConfig, fetch })).rejects.toThrow(
      '401 Unauthorized at https://discord.com/api/webhooks/123/abc'
    );
    const discordCall = calls.find((c) => c.url === baseConfig.discordWebhookUrl);
    expect(discordCall).toBeDefined();
  });

  it('uses Discord webhook URL from config for authentication', async () => {
    const customUrl = 'https://discord.com/api/webhooks/456/def';
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/issues/') && req.url.includes('/comments')) {
        return jsonResponse({ comments: [], pageInfo: { endCursor: '', hasMore: false } });
      }
      if (req.url === customUrl) {
        return jsonResponse({ id: 'msg-1' }, 200);
      }
      return jsonResponse({}, 404);
    });

    await handle(makePayload(), { ...baseConfig, discordWebhookUrl: customUrl, fetch });

    const discordCall = calls.find((c) => c.url === customUrl);
    expect(discordCall).toBeDefined();
    expect(discordCall?.method).toBe('POST');
    expect(calls.some((c) => c.url === baseConfig.discordWebhookUrl)).toBe(false);
  });

  it('falls back gracefully when Linear API fails', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/issues/') && req.url.includes('/comments')) {
        return jsonResponse({ error: 'Internal Server Error' }, 500);
      }
      if (req.url === baseConfig.discordWebhookUrl) {
        return jsonResponse({ id: 'msg-fallback' }, 200);
      }
      return jsonResponse({}, 404);
    });

    const result = await handle(makePayload(), { ...baseConfig, fetch });
    expect(result.discordMessageId).toBe('msg-fallback');

    const discordCall = calls.find((c) => c.url === baseConfig.discordWebhookUrl);
    expect(discordCall).toBeDefined();
    expect((discordCall?.json as any).content).toContain('(no comments)');
  });
});

